//! USLP Protocol Identifier, typed by a table generated from the SANA registry (732.1
//! §4.1.4.2.3; USLP-007, M2 plan D13, OI-06).
//!
//! The UPID is a 5-bit field of the TFDF Header whose values the SANA registry
//! `uslp_protocol_id` assigns (732.1 §4.1.4.2.3.3, reference \[14\]). No value is written here
//! from memory: [`Upid`] and its mapping are generated by `cargo xtask sana import
//! uslp_protocol_id` from the committed snapshot `specs/sana/uslp_protocol_id.tsv`, and
//! `cargo xtask sana` (part of `cargo xtask ci`) fails when the generated file differs from it.
//! A value the registry does not assign decodes as [`Upid::Other`] in both modes and raises no
//! anomaly (USLP-007).

mod table;

pub use table::Upid;

/// A 5-bit UPID value that the SANA registry does not assign (732.1 §4.1.4.2.3; USLP-007).
///
/// Built only by [`new`](Self::new), so an assigned value is always its named [`Upid`]
/// variant and never `Other` (RS-020).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct UnassignedUpid(u8);

impl UnassignedUpid {
    /// `value` if it is a 5-bit value the registry does not assign; `None` above 31 or for an
    /// assigned value (USLP-007).
    #[must_use]
    pub const fn new(value: u8) -> Option<UnassignedUpid> {
        if value > 0x1F || table::is_assigned(value) {
            None
        } else {
            Some(UnassignedUpid(value))
        }
    }

    /// The 5-bit value (USLP-007).
    #[must_use]
    pub const fn get(self) -> u8 {
        self.0
    }
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::{UnassignedUpid, Upid};

    #[test]
    fn every_value_round_trips() {
        // req: USLP-007
        for bits in 0..=31_u8 {
            let upid = Upid::from_bits(bits).unwrap();
            assert_eq!(upid.bits(), bits);
            match upid {
                Upid::Other(u) => assert_eq!(UnassignedUpid::new(bits), Some(u)),
                _ => assert_eq!(UnassignedUpid::new(bits), None),
            }
        }
        for bits in 32..=255_u8 {
            assert_eq!(Upid::from_bits(bits), None);
            assert_eq!(UnassignedUpid::new(bits), None);
        }
    }

    #[test]
    fn the_values_the_code_names() {
        // req: USLP-007, USLP-009
        // The names of 732.1 §4.1.4.1.9 and Annex D1.4.1.2 resolve to registry values, whatever
        // those are; the vectors pin the values the snapshot holds.
        assert!(!matches!(Upid::OnlyIdleData, Upid::Other(_)));
        assert_ne!(
            Upid::OnlyIdleData.bits(),
            Upid::MissionSpecificInformation1.bits()
        );
        let others = (0..=31).filter_map(UnassignedUpid::new).count();
        assert!(others < 32);
    }
}
